              // Handle specific quality names
              if (q === '4k' || q === '2160') return 2160;
              if (q === '1440') return 1440;
              if (q === '1080') return 1080;
              if (q === '720') return 720;
              if (q === '480') return 480;
              if (q === '360') return 360;
              if (q === '240') return 240;

